void loadSpriteBulletPalette(void) {
    if (spriteBullet.palette) {
        return;
    }
    const char *error = NULL;
    spriteBullet.palette = playdate->graphics->loadBitmapTable("sprites/sprite-bullet", &error);
    if (error) {
        playdate->system->error("Unable to load bitmap table of sprite Bullet: %s", error);
    }
}

